def build_question(q,opts,corr,why,c,n,phase):
 shift=(c+3*n+phase)%3;opts=opts[shift:]+opts[:shift]
 return {'q':q,'opciones':opts,'correcta':(corr-shift)%3,'porque':why}

updated=0
for f in sorted(R.glob('curso-*/modulo-*/leccion-*.html')):
 s=BeautifulSoup(f.read_text(),'html.parser'); h=s.select_one('header.hero h1');
 if not h:continue
 title=h.get_text(' ',strip=True)
 matching=next((t for rx,t in CONCRETE if re.search(rx,title,re.I)),None)
 if not matching:continue
 course=int(f.parts[-3].split('-')[-1]);n=int(f.stem.split('-')[-1]);
 quiz=s.select('.page > .micro-check script.quiz-data')
 if len(quiz)!=2:continue
 for i,script in enumerate(quiz):
  q,o,corr,why=matching[4*i:4*i+4];data=json.loads(script.string or script.get_text());data['preguntas']=[build_question(q,o,corr,why,course,n,i)];script.string=json.dumps(data,ensure_ascii=False)
 f.write_text(str(s),encoding='utf8');updated+=1
print('Lessons with two topic-specific questions:',updated)
